		String account = account();
		List<PostPayload> posts = new ArrayList<>();
		for (TaskDefinition task : tasks)
		{
			if (task.isOnce())
			{
				progressStore.markCompleted(task.getId());
			}
			posts.add(messageFormatter.build(account, task, party, completedAt));
		}
		postWithScreenshot(botTarget(), posts);
	}

	private boolean notYetPosted(TaskDefinition task)
	{
		return !task.isOnce() || !progressStore.isCompleted(task.getId());
	}

	private void warnIfCollectionLogChatDisabled()
	{
		RemoteConfig remoteConfig = remoteConfigService.current();
		if (!config.enabled() || remoteConfig == null)
		{
			return;
		}
		clogSettingCheckPending = false;
		int setting = client.getVarbitValue(VarbitID.OPTION_COLLECTION_NEW_ITEM);
		log.debug("Collection log notification setting is {}", setting);
		if ((setting & COLLECTION_LOG_CHAT_BIT) == 0 && !taskMatcher.byTrigger(remoteConfig, Triggers.CLOG).isEmpty())
		{
			warnInChat("Slay Clan: turn on the game setting 'Collection log - New addition notification', otherwise collection log tasks are not detected.");
		}
	}

	private void handleLoot(String source, Collection<ItemStack> items)
	{
		RemoteConfig remoteConfig = remoteConfigService.current();
		Player localPlayer = client.getLocalPlayer();
		if (!canPost() || remoteConfig == null || localPlayer == null)
		{
			return;
		}

		List<TaskDefinition> dropTasks = taskMatcher.byTrigger(remoteConfig, Triggers.DROP);
		List<TaskDefinition> lootTasks = taskMatcher.byTrigger(remoteConfig, Triggers.LOOT).stream()
			.filter(this::notYetPosted)
			.collect(Collectors.toList());
		if ((dropTasks.isEmpty() && lootTasks.isEmpty())
			|| !membershipChecker.isClan(client.getClanSettings(), remoteConfig.getClanName()))
		{
			log.debug("Ignoring loot from {}: no loot task or not in the configured clan", source);
			return;
		}

		List<PricedItem> pricedItems = items.stream().map(this::price).collect(Collectors.toList());
		Instant completedAt = Instant.now();
		String account = account();
		List<PostPayload> posts = new ArrayList<>();
		for (TaskDefinition task : dropTasks)
		{
			for (ValuableDrop drop : dropEvaluator.evaluate(pricedItems, task))
			{
				posts.add(messageFormatter.buildDrop(account, drop, source, completedAt));
			}
		}
		for (TaskDefinition task : lootTasks)
		{
			for (PricedItem item : pricedItems)
			{
				if (!lootTaskEvaluator.matches(task, source, item.getName()))
				{
					continue;
				}
				posts.add(messageFormatter.buildItemTask(account, task, item.getName(), source, completedAt));
				if (task.isOnce())
				{
					progressStore.markCompleted(task.getId());
					break;
				}
			}
		}
		if (!posts.isEmpty())
		{
			postWithScreenshot(botTarget(), posts);
		}
	}

	private PricedItem price(ItemStack item)
	{
		ItemComposition dropped = itemManager.getItemComposition(item.getId());
		int itemId = itemManager.canonicalize(item.getId());
		return new PricedItem(
			itemManager.getItemComposition(itemId).getName(),
			item.getQuantity(),
			itemManager.getItemPrice(itemId),
			dropped.isStackable());
	}

	private void postWithScreenshot(BotTarget target, List<PostPayload> posts)
	{
		screenshotService.capture(png -> posts.forEach(payload -> activityReporter.send(target, payload, png)));
	}

	/**
	 * Only one retry round runs at a time, otherwise two rounds started close together would both deliver the
	 * same post.
	 */
	private void retryPendingPosts()
	{
		RemoteConfig remoteConfig = remoteConfigService.current();
		if (!canPost() || remoteConfig == null || !retryInProgress.compareAndSet(false, true))
		{
			return;
		}
		try
		{
			activityReporter.retry(this::botTarget, pendingPostStore.load(Instant.now()))
				.whenComplete((ignored, error) -> retryInProgress.set(false));
		}
		catch (RuntimeException e)
		{
			log.warn("Retrying pending posts failed", e);
			retryInProgress.set(false);
		}
	}

	private boolean canPostForClan()
	{
		RemoteConfig remoteConfig = remoteConfigService.current();
		return canPost() && remoteConfig != null && client.getLocalPlayer() != null
			&& membershipChecker.isClan(client.getClanSettings(), remoteConfig.getClanName());
	}

	/**
	 * Posts need the member's clan token so the bot knows whose they are, and a profile that syncs to a RuneLite
	 * account so that one-time tasks are remembered across computers and shared with alts.
	 */
	private boolean canPost()
	{
		boolean canPost = config.enabled() && hasSecretSafeBotUrl() && !clanToken().isEmpty() && profileSyncsToAccount();
		if (!canPost && !postingBlockedLogged)
		{
			postingBlockedLogged = true;
			log.info("Posting blocked: enabled={}, bot URL usable={}, clan token set={}, profile synced={}",
				config.enabled(), hasSecretSafeBotUrl(), !clanToken().isEmpty(), profileSyncsToAccount());
		}
		return canPost;
	}

	// Posts carry the member's token
	private boolean hasSecretSafeBotUrl()
	{
		return SecretSafeUrl.accepts(botUrl());
	}

	private String botUrl()
	{
		return trimmed(config.botUrl());
	}

	private static String trimmed(String setting)
	{
		return setting == null ? "" : setting.trim();
	}

	// A synced profile needs a RuneLite account login, and it is the sync that carries the task memory along
	private boolean profileSyncsToAccount()
	{
		ConfigProfile profile = configManager.getProfile();
		return profile != null && profile.isSync();
	}

	private String clanToken()
	{
		return trimmed(config.clanToken());
	}

	private String account()
	{
		Player localPlayer = client.getLocalPlayer();
		return localPlayer == null || localPlayer.getName() == null ? "" : Text.sanitize(localPlayer.getName());
	}

	private void warnAboutSetup()
	{
		setupWarningPending = false;
		if (!config.enabled())
		{
			return;
		}
		warnIfBotUrlUnusable();
		if (clanToken().isEmpty())
		{
			warnInChat("Slay Clan: paste your clan token into the plugin settings, otherwise nothing is posted. Run /plugin token in the clan Discord to get one.");
		}
		if (!profileSyncsToAccount())
		{
			warnInChat("Slay Clan: log in with a RuneLite account and turn on Sync for this profile in the profile panel, otherwise nothing is posted.");
		}
		int dropped = pendingPostStore.takeDroppedCount();
		if (dropped > 0)
		{
			warnInChat("Slay Clan: " + dropped + " post(s) could not be delivered to the clan bot and were dropped. Submit those tasks manually.");
		}
		if (config.configUrl() == null || config.configUrl().trim().isEmpty())
		{
			warnInChat("Slay Clan: no clan config URL is set. Paste the URL from the clan Discord into the plugin settings.");
			return;
		}
		if (remoteConfigService.lastRefreshFailed())
		{
			warnInChat("Slay Clan: the clan config could not be loaded. Check the config URL in the plugin settings, or ask the clan staff if the config was changed.");
		}
		RemoteConfig remoteConfig = remoteConfigService.current();
		if (remoteConfig == null)
		{
			return;
		}
		boolean needsLootTracker = !taskMatcher.byTrigger(remoteConfig, Triggers.LOOT).isEmpty()
			|| !taskMatcher.byTrigger(remoteConfig, Triggers.DROP).isEmpty();
		boolean lootTrackerEnabled = pluginManager.getPlugins().stream()
			.anyMatch(plugin -> plugin instanceof LootTrackerPlugin && pluginManager.isPluginEnabled(plugin));
		if (needsLootTracker && !lootTrackerEnabled)
		{
			warnInChat("Slay Clan: enable the Loot Tracker plugin, otherwise drops and loot tasks are not detected.");
		}
	}

	private void warnInChat(String message)
	{
		client.addChatMessage(ChatMessageType.GAMEMESSAGE, "", ColorUtil.wrapWithColorTag(message, Color.RED), null);
	}

	// The bot answers on an HTTP thread, and the chat is only written from the client thread
	private void tell(BotReply reply)
	{
		if (reply.getMessage() == null || blockerAlreadySaid(reply))
		{
			return;
		}
		clientThread.invoke(() -> warnInChat("Slay Clan: " + reply.getMessage()));
	}

	private boolean blockerAlreadySaid(BotReply reply)
	{
		return reply.isBlocked() && !blockersSaid.add(reply.getBlocker());
	}

	// The setting was replaced by the clan token; the old value would otherwise sit in every profile for good
	private void forgetTheRetiredDiscordNameSetting()
	{
		configManager.unsetConfiguration(SlayClanConfig.GROUP, RETIRED_DISCORD_NAME_KEY);
	}

	@Provides
	SlayClanConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(SlayClanConfig.class);
	}
}

package com.slayclan.activity;

import com.google.gson.Gson;
import com.slayclan.discord.MessageFormatter;
import com.slayclan.discord.Nonce;
import com.slayclan.discord.PostKind;
import com.slayclan.discord.PostPayload;
import com.slayclan.trigger.TimedLine;
import java.time.Instant;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Locale;
import java.util.Map;
import lombok.Value;

/**
 * Builds the activity feed and PB posts. Field names are the bot's contract.
 */
public class ActivityFormatter
{
	@Value
	public static class Snapshot
	{
		PostPayload payload;
		String fingerprint;
	}

	private final Gson gson;

	public ActivityFormatter(Gson gson)
	{
		this.gson = gson;
	}

	public PostPayload clogEvent(String account, String item, int itemId, int quantity, int logSlots, Instant at)
	{
		Map<String, String> fields = new LinkedHashMap<>();
		fields.put("Item", item);
		fields.put("Item id", String.valueOf(itemId));
		fields.put("Quantity", String.valueOf(quantity));
		fields.put("Log slots", String.valueOf(logSlots));
		return MessageFormatter.payload(PostKind.CLOG, account, fields, at);
	}

	public PostPayload caEvent(String account, String task, int taskId, String tier, Instant at)
	{
		Map<String, String> fields = new LinkedHashMap<>();
		fields.put("Task", task);
		fields.put("Task id", String.valueOf(taskId));
		fields.put("Tier", tier);
		return MessageFormatter.payload(PostKind.CA, account, fields, at);
	}

	public PostPayload status(String account, CombatAchievementStatus ca, CollectionLogStatus clog, Instant at)
	{
		Map<String, String> fields = new LinkedHashMap<>();
		fields.put("CA completed", ca.completedText());
		fields.put("CA points", String.valueOf(ca.points()));
		fields.put("CA tier status", ca.tierStatusText());
		fields.put("Log slots", clog.slotsText());
		fields.put("Log categories", clog.categoriesText());
		return MessageFormatter.payload(PostKind.STATUS, account, fields, at);
	}

	public Snapshot caSnapshot(String account, long accountHash, List<CompletedAchievement> tasks, Instant at)
	{
		return snapshot(PostKind.CA_SNAPSHOT, account, accountHash, tasks, at);
	}

	public Snapshot clogSnapshot(String account, long accountHash, List<OwnedItem> items, Instant at)
	{
		return snapshot(PostKind.CLOG_SNAPSHOT, account, accountHash, items, at);
	}

	public Snapshot pbSnapshot(String account, long accountHash, List<StoredPersonalBest> bests, Instant at)
	{
		return snapshot(PostKind.PB_SNAPSHOT, account, accountHash, bests, at);
	}

	/**
	 * The party is the clan members who fought, so the bot can give every one of them their leaderboard row at once
	 * (decided 2026-10-22); only all-clan teams reach this point, so no outsider's name leaves the client.
	 */
	public PostPayload personalBest(String account, String boss, String time, TimedLine.Kind kind, int teamSize, List<String> party,
		PersonalBestClaim claim, Instant at)
	{
		Map<String, String> fields = new LinkedHashMap<>();
		fields.put("Boss", boss);
		fields.put("Time", time);
		fields.put("Time type", timeType(kind));
		fields.put("Team size", String.valueOf(teamSize));
		fields.put("Party", String.join(", ", party));
		fields.put("New", claim.isNewRecord() ? "yes" : "no");
		return personalBestPayload(account, fields, claim, at);
	}

	/**
	 * The game keeps one personal best per boss across team sizes (raids are per size), so a current best reported
	 * at a later kill may come from another scale than today's party. No team size or party is claimed for it.
	 */
	public PostPayload currentBossBest(String account, String boss, String time, TimedLine.Kind kind, Instant at)
	{
		Map<String, String> fields = new LinkedHashMap<>();
		fields.put("Boss", boss);
		fields.put("Time", time);
		fields.put("Time type", timeType(kind));
		fields.put("Scale", "unknown, the game keeps one personal best per boss");
		fields.put("New", "no");
		return personalBestPayload(account, fields, PersonalBestClaim.CURRENT, at);
	}

	// A current best is reported so the board can be filled in, not because of this kill, so it gets no chat line
	private static PostPayload personalBestPayload(String account, Map<String, String> fields, PersonalBestClaim claim, Instant at)
	{
		return new PostPayload(PostKind.PB.getName(), Nonce.next(), account, null, at.toString(), fields, null,
			claim == PersonalBestClaim.CURRENT);
	}

	private static String timeType(TimedLine.Kind kind)
	{
		return kind.name().toLowerCase(Locale.ROOT);
	}

	/**
	 * The fingerprint covers the entries only, so a snapshot taken later with the same content counts as unchanged.
	 */
	private Snapshot snapshot(PostKind kind, String account, long accountHash, List<?> entries, Instant at)
	{
		Map<String, String> fields = new LinkedHashMap<>();
		fields.put("Items", String.valueOf(entries.size()));
		PostPayload payload = new PostPayload(kind.getName(), Nonce.next(), account, String.valueOf(accountHash), at.toString(),
			fields, entries, false);
		return new Snapshot(payload, DeliveredSnapshots.fingerprint(gson.toJson(entries)));
	}
}

package com.slayclan.activity;

import com.slayclan.discord.BotClient;
import com.slayclan.discord.BotReply;
import com.slayclan.discord.BotTarget;
import com.slayclan.discord.PendingPost;
import com.slayclan.discord.PendingPostStore;
import com.slayclan.discord.PostKind;
import com.slayclan.discord.PostPayload;
import java.time.Instant;
import java.util.List;
import java.util.Map;
import java.util.concurrent.CompletableFuture;
import java.util.concurrent.ConcurrentHashMap;
import java.util.function.Consumer;
import java.util.function.Supplier;
import lombok.extern.slf4j.Slf4j;

/**
 * Sends posts to the bot and settles what comes back: the answer goes to the chat, a post the bot could not
 * take is kept for retry. Status and snapshots are only sent when their content differs from what the bot
 * last accepted for the account, and are not kept, since the next login or log opening sends a fresh one when
 * needed.
 */
@Slf4j
public class ActivityReporter
{
	private final ActivityFormatter formatter;
	private final BotClient botClient;
	private final PendingPostStore pendingPostStore;
	private final DeliveredSnapshots deliveredSnapshots;
	private final Consumer<BotReply> tell;
	// A second check can run before the bot has answered the first send, so the fingerprint last sent per kind and
	// account counts as delivered meanwhile, and only that one is remembered when the bot answers, however the
	// answers are ordered
	private final Map<String, String> lastSent = new ConcurrentHashMap<>();

	public ActivityReporter(ActivityFormatter formatter, BotClient botClient, PendingPostStore pendingPostStore,
		DeliveredSnapshots deliveredSnapshots, Consumer<BotReply> tell)
	{
		this.formatter = formatter;
		this.botClient = botClient;
		this.pendingPostStore = pendingPostStore;
		this.deliveredSnapshots = deliveredSnapshots;
		this.tell = tell;
	}

	/**
	 * Sends a post the member just earned and keeps it when the bot could not take it.
	 */
	public CompletableFuture<Void> send(BotTarget target, PostPayload payload, byte[] png)
	{
		return botClient.send(target, payload, png).thenAccept(reply -> settle(reply, payload));
	}

	/**
	 * Sends kept posts one at a time, dropping each the bot took. The target is read again for every post, so a
	 * Clan bot URL changed during the round is followed. Stops at a blocked post, since every post after it would
	 * fail the same way.
	 */
	public CompletableFuture<Void> retry(Supplier<BotTarget> target, List<PendingPost> pending)
	{
		if (pending.isEmpty())
		{
			return CompletableFuture.completedFuture(null);
		}
		PendingPost first = pending.get(0);
		return botClient.send(target.get(), first.getPayload(), null).thenCompose(reply ->
		{
			tell.accept(reply);
			if (reply.isDelivered())
			{
				pendingPostStore.remove(first);
			}
			if (reply.isBlocked())
			{
				return CompletableFuture.completedFuture(null);
			}
			return retry(target, pending.subList(1, pending.size()));
		});
	}

	public void reportClog(BotTarget target, String account, String item, int itemId, int quantity, int logSlots)
	{
		send(target, formatter.clogEvent(account, item, itemId, quantity, logSlots, Instant.now()), null);
	}

	public void reportCa(BotTarget target, String account, String task, int taskId, String tier)
	{
		send(target, formatter.caEvent(account, task, taskId, tier, Instant.now()), null);
	}

	public void reportStatusIfChanged(BotTarget target, String account, long accountHash, CombatAchievementStatus ca,
		CollectionLogStatus clog)
	{
		String fingerprint = DeliveredSnapshots.fingerprint(
			String.join("|", account, ca.completedText(), ca.tierStatusText(), clog.slotsText(), clog.categoriesText()));
		sendIfChanged(target, PostKind.STATUS, accountHash, fingerprint, formatter.status(account, ca, clog, Instant.now()));
	}

	public void reportCaSnapshot(BotTarget target, String account, long accountHash, List<CompletedAchievement> tasks)
	{
		sendIfChanged(target, PostKind.CA_SNAPSHOT, accountHash, formatter.caSnapshot(account, accountHash, tasks, Instant.now()));
	}

	public void reportClogSnapshot(BotTarget target, String account, long accountHash, List<OwnedItem> items)
	{
		sendIfChanged(target, PostKind.CLOG_SNAPSHOT, accountHash, formatter.clogSnapshot(account, accountHash, items, Instant.now()));
	}

	public void reportPbSnapshot(BotTarget target, String account, long accountHash, List<StoredPersonalBest> bests)
	{
		sendIfChanged(target, PostKind.PB_SNAPSHOT, accountHash, formatter.pbSnapshot(account, accountHash, bests, Instant.now()));
	}

	private void sendIfChanged(BotTarget target, PostKind kind, long accountHash, ActivityFormatter.Snapshot snapshot)
	{
		sendIfChanged(target, kind, accountHash, snapshot.getFingerprint(), snapshot.getPayload());
	}

	private void sendIfChanged(BotTarget target, PostKind kind, long accountHash, String fingerprint, PostPayload payload)
	{
		String key = kind + ":" + accountHash;
		if (alreadyDeliveredOrOnItsWay(kind, accountHash, fingerprint, key))
		{
			log.debug("{} unchanged since last delivery or already being sent, not sent", kind);
			return;
		}
		lastSent.put(key, fingerprint);
		botClient.send(target, payload, null).thenAccept(reply ->
		{
			tell.accept(reply);
			if (!reply.isDelivered())
			{
				log.info("{} not delivered, it is sent again next time", kind);
				lastSent.remove(key, fingerprint);
			}
			else if (lastSent.remove(key, fingerprint))
			{
				deliveredSnapshots.markDelivered(kind, accountHash, fingerprint);
			}
		});
	}

	private boolean alreadyDeliveredOrOnItsWay(PostKind kind, long accountHash, String fingerprint, String key)
	{
		return deliveredSnapshots.isDelivered(kind, accountHash, fingerprint) || fingerprint.equals(lastSent.get(key));
	}

	private void settle(BotReply reply, PostPayload payload)
	{
		tell.accept(reply);
		if (!reply.isDelivered())
		{
			log.info("Keeping an undelivered {} post for retry", payload.getKind());
			pendingPostStore.add(payload, Instant.now());
		}
	}
}

package com.slayclan.activity;

import com.slayclan.task.Names;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.Optional;
import java.util.function.BooleanSupplier;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.EnumComposition;
import net.runelite.api.MenuAction;
import net.runelite.api.events.ScriptPostFired;
import net.runelite.api.events.ScriptPreFired;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.gameval.VarbitID;
import net.runelite.client.game.ItemManager;

/**
 * Captures the full collection log the way RuneProfile and WikiSync do: when the player opens their own log,
 * the game's search is triggered, which makes the server send one script 4100 call per owned item.
 */
@Slf4j
public class CollectionLogCapture
{
	// Neither gameval nor net.runelite.api.ScriptID names these scripts and this enum; the ids come from WikiSync and RuneProfile
	public static final int COLLECTION_LOG_SETUP = 7797;
	public static final int COLLECTION_TRANSMIT = 4100;
	static final int COLLECTION_INIT = 2240;
	static final int ITEM_REPLACEMENTS = 3721;
	private static final int SETTLE_TICKS = 2;
	// A capture that gets no items, because the log was closed at once or the search did not open, must not swallow the next opening
	static final int NO_ITEMS_TIMEOUT_TICKS = 50;

	private final Client client;
	private final ItemManager itemManager;
	private final BooleanSupplier captureWanted;
	private boolean captureAllowed;
	private boolean capturing;
	private final List<OwnedItem> items = new ArrayList<>();
	private int captureStartTick = -1;
	private int lastTransmitTick = -1;

	public CollectionLogCapture(Client client, ItemManager itemManager, BooleanSupplier captureWanted)
	{
		this.client = client;
		this.itemManager = itemManager;
		this.captureWanted = captureWanted;
	}

	public void onLogin()
	{
		captureAllowed = true;
		reset();
	}

	/**
	 * Lets the next opening of the log capture again, for when the captured list could not be used.
	 */
	public void allowAgain()
	{
		captureAllowed = true;
	}

	public void onScriptPostFired(ScriptPostFired event)
	{
		if (event.getScriptId() != COLLECTION_LOG_SETUP || !shouldStartCapture())
		{
			return;
		}
		captureAllowed = false;
		capturing = true;
		captureStartTick = client.getTickCount();
		client.menuAction(-1, InterfaceID.Collection.SEARCH_TOGGLE, MenuAction.CC_OP, 1, -1, "Search", null);
		client.runScript(COLLECTION_INIT);
	}

	public void onScriptPreFired(ScriptPreFired event)
	{
		if (event.getScriptId() != COLLECTION_TRANSMIT || !capturing)
		{
			return;
		}
		Object[] args = event.getScriptEvent().getArguments();
		int itemId = (int) args[1];
		int quantity = (int) args[2];
		items.add(new OwnedItem(itemId, itemManager.getItemComposition(itemId).getName(), quantity));
		lastTransmitTick = client.getTickCount();
	}

	public Optional<List<OwnedItem>> onTick(int tick)
	{
		if (captureGaveNothing(tick))
		{
			log.debug("Collection log capture got no items, allowing the next opening to try again");
			reset();
			captureAllowed = true;
			return Optional.empty();
		}
		if (!captureSettled(tick))
		{
			return Optional.empty();
		}
		List<OwnedItem> captured = distinctItems();
		reset();
		return Optional.of(captured);
	}

	private void reset()
	{
		capturing = false;
		items.clear();
		captureStartTick = -1;
		lastTransmitTick = -1;
	}

	/**
	 * The game sends an item once per log page it appears on, and some items have a replacement id (enum 3721,
	 * as WikiSync uses it), so the list is folded to one entry per item, matching the game's own slot count.
	 * Items the enum does not cover but which the game still sends under two ids, such as the Prospector set
	 * (12013 and 29472), share one name, so a second pass folds on the name and keeps the lowest id.
	 */
	private List<OwnedItem> distinctItems()
	{
		Map<Integer, Integer> replacements = replacementIds();
		log.debug("Collection log capture folding {} items with {} replacement ids", items.size(), replacements.size());
		Map<Integer, OwnedItem> byId = new LinkedHashMap<>();
		for (OwnedItem item : items)
		{
			int id = replacements.getOrDefault(item.getId(), item.getId());
			if (higherQuantityThanKnown(item, byId.get(id)))
			{
				byId.put(id, new OwnedItem(id, item.getName(), item.getQuantity()));
			}
		}
		Map<String, OwnedItem> byName = new LinkedHashMap<>();
		for (OwnedItem item : byId.values())
		{
			String name = Names.normalize(item.getName());
			OwnedItem known = byName.get(name);
			if (known == null)
			{
				byName.put(name, item);
			}
			else
			{
				byName.put(name, new OwnedItem(Math.min(known.getId(), item.getId()), known.getName(),
					Math.max(known.getQuantity(), item.getQuantity())));
			}
		}
		return new ArrayList<>(byName.values());
	}

	private static boolean higherQuantityThanKnown(OwnedItem item, OwnedItem known)
	{
		return known == null || item.getQuantity() > known.getQuantity();
	}

	private Map<Integer, Integer> replacementIds()
	{
		EnumComposition replacements = client.getEnum(ITEM_REPLACEMENTS);
		Map<Integer, Integer> ids = new HashMap<>();
		if (replacements == null)
		{
			return ids;
		}
		int[] from = replacements.getKeys();
		int[] to = replacements.getIntVals();
		for (int i = 0; i < Math.min(from.length, to.length); i++)
		{
			ids.put(from[i], to[i]);
		}
		return ids;
	}

	private boolean shouldStartCapture()
	{
		return captureAllowed && !capturing && captureWanted.getAsBoolean() && isOwnLog();
	}

	private boolean isOwnLog()
	{
		return client.getVarbitValue(VarbitID.COLLECTION_POH_HOST_BOOK_OPEN) == 0;
	}

	private boolean captureSettled(int tick)
	{
		return capturing && lastTransmitTick != -1 && tick - lastTransmitTick >= SETTLE_TICKS;
	}

	private boolean captureGaveNothing(int tick)
	{
		return capturing && lastTransmitTick == -1 && tick - captureStartTick > NO_ITEMS_TIMEOUT_TICKS;
	}
}

package com.slayclan.activity;

import java.util.stream.IntStream;
import net.runelite.api.Client;
import net.runelite.api.gameval.VarPlayerID;

public class CollectionLogReader
{
	private static final int[] CATEGORY_OBTAINED = {
		VarPlayerID.COLLECTION_COUNT_BOSSES, VarPlayerID.COLLECTION_COUNT_RAIDS, VarPlayerID.COLLECTION_COUNT_CLUES,
		VarPlayerID.COLLECTION_COUNT_MINIGAMES, VarPlayerID.COLLECTION_COUNT_OTHER
	};
	private static final int[] CATEGORY_MAX = {
		VarPlayerID.COLLECTION_COUNT_BOSSES_MAX, VarPlayerID.COLLECTION_COUNT_RAIDS_MAX, VarPlayerID.COLLECTION_COUNT_CLUES_MAX,
		VarPlayerID.COLLECTION_COUNT_MINIGAMES_MAX, VarPlayerID.COLLECTION_COUNT_OTHER_MAX
	};

	private final Client client;

	public CollectionLogReader(Client client)
	{
		this.client = client;
	}

	public static boolean readsVarp(int varpId)
	{
		return varpId == VarPlayerID.COLLECTION_COUNT || varpId == VarPlayerID.COLLECTION_COUNT_MAX
			|| contains(CATEGORY_OBTAINED, varpId) || contains(CATEGORY_MAX, varpId);
	}

	private static boolean contains(int[] ids, int id)
	{
		return IntStream.of(ids).anyMatch(candidate -> candidate == id);
	}

	public CollectionLogStatus read()
	{
		return new CollectionLogStatus(
			client.getVarpValue(VarPlayerID.COLLECTION_COUNT),
			client.getVarpValue(VarPlayerID.COLLECTION_COUNT_MAX),
			varps(CATEGORY_OBTAINED),
			varps(CATEGORY_MAX));
	}

	private int[] varps(int[] ids)
	{
		int[] values = new int[ids.length];
		for (int i = 0; i < ids.length; i++)
		{
			values[i] = client.getVarpValue(ids[i]);
		}
		return values;
	}
}

