package com.slayclan.activity;

import com.slayclan.SlayClanConfig;
import com.slayclan.discord.PostKind;
import java.nio.charset.StandardCharsets;
import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;
import java.util.Locale;
import net.runelite.client.config.ConfigManager;

/**
 * Remembers the content of the last snapshot and status post Discord accepted per account, so that logins and
 * world hops only post when something changed. A failed delivery is not remembered and is tried again next time.
 */
public class DeliveredSnapshots
{
	private static final String PREFIX = "snapshot.";

	private final ConfigManager configManager;

	public DeliveredSnapshots(ConfigManager configManager)
	{
		this.configManager = configManager;
	}

	public boolean isDelivered(PostKind kind, long accountHash, String fingerprint)
	{
		return fingerprint.equals(configManager.getConfiguration(SlayClanConfig.MEMORY_GROUP, key(kind, accountHash)));
	}

	public void markDelivered(PostKind kind, long accountHash, String fingerprint)
	{
		configManager.setConfiguration(SlayClanConfig.MEMORY_GROUP, key(kind, accountHash), fingerprint);
	}

	public static String fingerprint(String content)
	{
		try
		{
			byte[] digest = MessageDigest.getInstance("SHA-256").digest(content.getBytes(StandardCharsets.UTF_8));
			StringBuilder hex = new StringBuilder();
			for (byte b : digest)
			{
				hex.append(String.format("%02x", b));
			}
			return hex.toString();
		}
		catch (NoSuchAlgorithmException e)
		{
			throw new IllegalStateException("SHA-256 is required by every Java runtime", e);
		}
	}

	private static String key(PostKind kind, long accountHash)
	{
		return PREFIX + kind.name().toLowerCase(Locale.ROOT) + "." + accountHash;
	}
}

package com.slayclan.activity;

import com.slayclan.task.Names;
import java.util.HashMap;
import java.util.Map;
import java.util.OptionalInt;
import net.runelite.api.Client;
import net.runelite.api.ItemComposition;

/**
 * Item name to id for every item in the cache, built a slice per game tick on the client thread. RuneLite's own
 * item search only knows tradeable items, so collection log items such as pets and notes need this.
 */
public class ItemNameIndex
{
	static final int ITEMS_PER_TICK = 2000;

	private final Client client;
	private final Map<String, Integer> idsByName = new HashMap<>();
	private int nextId;
	private boolean complete;

	public ItemNameIndex(Client client)
	{
		this.client = client;
	}

	public void onTick()
	{
		if (complete)
		{
			return;
		}
		int count = client.getItemCount();
		int end = Math.min(count, nextId + ITEMS_PER_TICK);
		for (int id = nextId; id < end; id++)
		{
			remember(id, client.getItemDefinition(id));
		}
		nextId = end;
		complete = nextId >= count && count > 0;
	}

	public OptionalInt idOf(String name)
	{
		Integer id = idsByName.get(key(name));
		return id == null ? OptionalInt.empty() : OptionalInt.of(id);
	}

	// Noted and placeholder variants share the real item's name; the first real id is the one the log shows
	private void remember(int id, ItemComposition item)
	{
		if (item == null || item.getName() == null || item.getNote() != -1 || item.getPlaceholderTemplateId() != -1)
		{
			return;
		}
		idsByName.putIfAbsent(key(item.getName()), id);
	}

	private static String key(String name)
	{
		return Names.normalize(name);
	}
}

