package com.slayclan.config;

import com.google.gson.Gson;
import com.google.gson.JsonElement;
import com.google.gson.JsonObject;
import com.google.gson.JsonParseException;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.HashSet;
import java.util.List;
import java.util.Map;
import java.util.Optional;
import java.util.Set;
import lombok.extern.slf4j.Slf4j;

/**
 * Reads the clan config. "tasks" is either a list of tasks or an object whose keys are tier names and whose
 * values are lists of tasks. In the grouped form a task without its own "tier" gets the group's name.
 */
@Slf4j
public class RemoteConfigParser
{
	private final Gson gson;

	public RemoteConfigParser(Gson gson)
	{
		this.gson = gson;
	}

	public Optional<RemoteConfig> parse(String json)
	{
		RemoteConfig config;
		try
		{
			config = toConfig(gson.fromJson(json, JsonObject.class));
		}
		catch (JsonParseException | IllegalStateException | UnsupportedOperationException e)
		{
			return Optional.empty();
		}

		return isUsable(config) ? Optional.of(config) : Optional.empty();
	}

	private static boolean isUsable(RemoteConfig config)
	{
		return config != null && hasRequiredFields(config) && hasUniqueIds(config.getTasks());
	}

	private static boolean hasRequiredFields(RemoteConfig config)
	{
		return !isBlank(config.getClanName()) && config.getTasks() != null;
	}

	/**
	 * One-time memory is keyed by id, so a missing or repeated id would make unrelated tasks share it. RuneLite
	 * refuses config keys containing ':', so such an id could never be remembered.
	 */
	private static boolean hasUniqueIds(List<TaskDefinition> tasks)
	{
		Set<String> seen = new HashSet<>();
		for (TaskDefinition task : tasks)
		{
			if (isBlank(task.getId()))
			{
				log.info("Clan config rejected: task '{}' has no id", task.getName());
				return false;
			}
			if (task.getId().contains(":"))
			{
				log.info("Clan config rejected: task id '{}' contains ':'", task.getId());
				return false;
			}
			if (!seen.add(task.getId().trim()))
			{
				log.info("Clan config rejected: task id '{}' is used more than once", task.getId());
				return false;
			}
		}
		return true;
	}

	private RemoteConfig toConfig(JsonObject root)
	{
		if (root == null)
		{
			return null;
		}
		RemoteConfig config = new RemoteConfig();
		config.setClanName(string(root, "clanName"));
		config.setTasks(tasks(root.get("tasks")));
		config.setIgnoredContent(strings(root.get("ignoredContent")));
		return config;
	}

	/**
	 * The switch-off list is edited in a hurry, so a single name written without brackets counts as a list of one
	 * instead of rejecting the whole config and silencing every post.
	 */
	private List<String> strings(JsonElement element)
	{
		if (element == null || element.isJsonNull())
		{
			return List.of();
		}
		if (element.isJsonPrimitive())
		{
			return List.of(element.getAsString());
		}
		return Arrays.asList(gson.fromJson(element, String[].class));
	}

	private List<TaskDefinition> tasks(JsonElement element)
	{
		if (element == null || element.isJsonNull())
		{
			return null;
		}
		if (element.isJsonArray())
		{
			return new ArrayList<>(Arrays.asList(gson.fromJson(element, TaskDefinition[].class)));
		}
		List<TaskDefinition> tasks = new ArrayList<>();
		for (Map.Entry<String, JsonElement> group : element.getAsJsonObject().entrySet())
		{
			for (TaskDefinition task : gson.fromJson(group.getValue().getAsJsonArray(), TaskDefinition[].class))
			{
				if (task.getTier() == null)
				{
					task.setTier(group.getKey());
				}
				tasks.add(task);
			}
		}
		return tasks;
	}

	private static String string(JsonObject root, String key)
	{
		JsonElement value = root.get(key);
		return value == null || value.isJsonNull() ? null : value.getAsString();
	}

	private static boolean isBlank(String value)
	{
		return value == null || value.trim().isEmpty();
	}
}

package com.slayclan.config;

import com.google.gson.Gson;
import java.io.IOException;
import java.util.Objects;
import java.util.concurrent.CompletableFuture;
import java.util.concurrent.atomic.AtomicBoolean;
import java.util.concurrent.atomic.AtomicLong;
import java.util.concurrent.atomic.AtomicReference;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;
import okhttp3.Call;
import okhttp3.Callback;
import okhttp3.HttpUrl;
import okhttp3.OkHttpClient;
import okhttp3.Request;
import okhttp3.Response;
import okhttp3.ResponseBody;
import okio.BufferedSource;

@Slf4j
@Singleton
public class RemoteConfigService
{
	// A real clan config is a few tens of kB; anything bigger is a wrong URL or a hostile host
	static final long MAX_BODY_BYTES = 1_000_000;

	private final OkHttpClient httpClient;
	private final RemoteConfigParser parser;
	private final AtomicReference<RemoteConfig> current = new AtomicReference<>();
	private final AtomicReference<String> currentUrl = new AtomicReference<>();
	private final AtomicBoolean lastRefreshFailed = new AtomicBoolean();
	private final AtomicLong latestRefresh = new AtomicLong();

	@Inject
	public RemoteConfigService(OkHttpClient httpClient, Gson gson)
	{
		this.httpClient = httpClient;
		this.parser = new RemoteConfigParser(gson);
	}

	public RemoteConfig current()
	{
		return current.get();
	}

	/**
	 * True when the most recent refresh could not fetch or parse the config, so {@link #current()} is stale or
	 * missing.
	 */
	public boolean lastRefreshFailed()
	{
		return lastRefreshFailed.get();
	}

	/**
	 * A failed refresh keeps the previous config only while the URL is unchanged, so that switching to a broken
	 * URL cannot keep the old clan's tasks. Only the most recent refresh may change the config, so a slow
	 * response for an old URL cannot overwrite a newer one.
	 */
	public CompletableFuture<Void> refresh(String url)
	{
		long generation = latestRefresh.incrementAndGet();
		if (url == null || url.trim().isEmpty())
		{
			log.debug("No clan config URL, clearing config");
			setCurrent(null, null);
			lastRefreshFailed.set(false);
			return CompletableFuture.completedFuture(null);
		}
		HttpUrl httpUrl = HttpUrl.parse(url.trim());
		if (httpUrl == null || !SecretSafeUrl.accepts(httpUrl))
		{
			log.info("Clan config URL is not a valid https URL");
			setCurrent(null, null);
			lastRefreshFailed.set(true);
			return CompletableFuture.completedFuture(null);
		}

		CompletableFuture<Void> done = new CompletableFuture<>();
		Request request = new Request.Builder().url(httpUrl).build();
		httpClient.newCall(request).enqueue(new Callback()
		{
			@Override
			public void onFailure(Call call, IOException e)
			{
				log.info("Failed to fetch clan config", e);
				fail(url, generation);
				done.complete(null);
			}

			@Override
			public void onResponse(Call call, Response response) throws IOException
			{
				try (ResponseBody body = response.body())
				{
					if (!response.isSuccessful() || body == null)
					{
						log.info("Clan config request returned {}", response.code());
						fail(url, generation);
						return;
					}
					if (!SecretSafeUrl.accepts(response.request().url()))
					{
						log.info("Clan config URL redirected to a plain http URL, ignoring it");
						fail(url, generation);
						return;
					}
					BufferedSource source = body.source();
					if (source.request(MAX_BODY_BYTES + 1))
					{
						log.info("Clan config is larger than {} bytes, ignoring it", MAX_BODY_BYTES);
						fail(url, generation);
						return;
					}
					String json = source.readUtf8();
					synchronized (RemoteConfigService.this)
					{
						if (generation != latestRefresh.get())
						{
							return;
						}
						parser.parse(json).ifPresentOrElse(
							parsed ->
							{
								setCurrent(parsed, url);
								lastRefreshFailed.set(false);
							},
							() ->
							{
								log.info("Clan config invalid");
								fail(url, generation);
							});
					}
				}
				finally
				{
					done.complete(null);
				}
			}
		});
		return done;
	}

	private synchronized void fail(String url, long generation)
	{
		if (generation != latestRefresh.get())
		{
			return;
		}
		lastRefreshFailed.set(true);
		if (!Objects.equals(url, currentUrl.get()))
		{
			setCurrent(null, null);
		}
	}

	private synchronized void setCurrent(RemoteConfig config, String url)
	{
		current.set(config);
		currentUrl.set(url);
	}
}

package com.slayclan.config;

import java.util.regex.Pattern;
import okhttp3.HttpUrl;

/**
 * Where a request that carries a secret, the clan token or the config URL, may go: over TLS, or in plain
 * http only to this computer, where nothing can sit in between, which lets a local test bot and config server
 * work. Decided on the parsed URL, since a prefix check is fooled by userinfo such as
 * {@code http://localhost:@evil.example/}.
 */
public final class SecretSafeUrl
{
	private static final Pattern LOOPBACK_IPV4 = Pattern.compile("127(\\.\\d{1,3}){3}");

	private SecretSafeUrl()
	{
	}

	public static boolean accepts(String url)
	{
		HttpUrl parsed = url == null ? null : HttpUrl.parse(url);
		return parsed != null && accepts(parsed);
	}

	public static boolean accepts(HttpUrl url)
	{
		return url.isHttps() || isThisComputer(url.host());
	}

	private static boolean isThisComputer(String host)
	{
		return "localhost".equals(host) || LOOPBACK_IPV4.matcher(host).matches() || "::1".equals(host);
	}
}

