package com.slayclan.progress;

import com.slayclan.SlayClanConfig;
import java.util.Arrays;
import java.util.Collections;
import java.util.Set;
import java.util.TreeSet;
import java.util.stream.Collectors;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.client.config.ConfigManager;

/**
 * Memory of posted one-time tasks and partial collection log progress. It lives in the RuneLite profile, so a
 * main and its alts on the same profile share it, as the clan counts them as one player.
 */
@Singleton
public class TaskProgressStore
{
	private static final String COMPLETED_PREFIX = "completed.";
	private static final String CLOG_PREFIX = "clog.";
	private static final String BASELINE_PREFIX = "baseline.";
	private static final String ITEM_SEPARATOR = "|";

	private final ConfigManager configManager;

	@Inject
	public TaskProgressStore(ConfigManager configManager)
	{
		this.configManager = configManager;
	}

	public boolean isCompleted(String taskId)
	{
		return "true".equals(configManager.getConfiguration(SlayClanConfig.MEMORY_GROUP, COMPLETED_PREFIX + taskId));
	}

	public void markCompleted(String taskId)
	{
		configManager.setConfiguration(SlayClanConfig.MEMORY_GROUP, COMPLETED_PREFIX + taskId, "true");
	}

	public Set<String> loggedItems(String taskId)
	{
		String stored = configManager.getConfiguration(SlayClanConfig.MEMORY_GROUP, CLOG_PREFIX + taskId);
		if (stored == null || stored.isEmpty())
		{
			return Collections.emptySet();
		}
		return Arrays.stream(stored.split("\\" + ITEM_SEPARATOR)).collect(Collectors.toSet());
	}

	public void saveLoggedItems(String taskId, Set<String> items)
	{
		configManager.setConfiguration(SlayClanConfig.MEMORY_GROUP, CLOG_PREFIX + taskId,
			String.join(ITEM_SEPARATOR, new TreeSet<>(items)));
	}

	/**
	 * A task is baselined once the plugin has recorded whether its condition was already met for this account,
	 * so that only conditions met afterwards get posted. Completion is shared across the profile, the baseline
	 * is not, as an alt that lacks an item says nothing about the main.
	 */
	public boolean isBaselined(String taskId, long accountHash)
	{
		return "true".equals(configManager.getConfiguration(SlayClanConfig.MEMORY_GROUP, baselineKey(taskId, accountHash)));
	}

	public void markBaselined(String taskId, long accountHash)
	{
		configManager.setConfiguration(SlayClanConfig.MEMORY_GROUP, baselineKey(taskId, accountHash), "true");
	}

	private static String baselineKey(String taskId, long accountHash)
	{
		return BASELINE_PREFIX + taskId + "." + accountHash;
	}
}

package com.slayclan.raid;

import com.slayclan.trigger.Triggers;
import java.util.Arrays;
import java.util.Collections;
import java.util.List;
import java.util.Objects;
import java.util.stream.Collectors;
import javax.inject.Inject;
import net.runelite.api.Actor;
import net.runelite.api.Client;
import net.runelite.api.WorldView;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.gameval.VarClientID;
import net.runelite.api.gameval.VarbitID;
import net.runelite.api.widgets.Widget;
import net.runelite.client.util.Text;

/**
 * Raids read the party list, which includes dead or far away members: Chambers of Xeric from its raid side
 * panel, Theatre of Blood, Tombs of Amascut and the Fractured Archive from varclients. Everything else, and
 * any raid whose list is unavailable, falls back to the players currently in the scene.
 */
public class RaidParticipantReader
{
	private static final String THEATRE_OF_BLOOD = Triggers.RAID_PREFIX + "Theatre of Blood";
	private static final String CHAMBERS_OF_XERIC = Triggers.RAID_PREFIX + "Chambers of Xeric";
	private static final String TOMBS_OF_AMASCUT = Triggers.RAID_PREFIX + "Tombs of Amascut";
	private static final String FRACTURED_ARCHIVE = Triggers.RAID_PREFIX + "Fractured Archive";
	private static final int[] TOB_PARTY_NAMES = {
		VarClientID.TOB_CLIENT_NAME0, VarClientID.TOB_CLIENT_NAME1, VarClientID.TOB_CLIENT_NAME2,
		VarClientID.TOB_CLIENT_NAME3, VarClientID.TOB_CLIENT_NAME4
	};
	private static final int[] TOA_PARTY_NAMES = {
		VarClientID.TOA_CLIENT_NAME0, VarClientID.TOA_CLIENT_NAME1, VarClientID.TOA_CLIENT_NAME2,
		VarClientID.TOA_CLIENT_NAME3, VarClientID.TOA_CLIENT_NAME4, VarClientID.TOA_CLIENT_NAME5,
		VarClientID.TOA_CLIENT_NAME6, VarClientID.TOA_CLIENT_NAME7
	};
	private static final int[] TFA_PARTY_NAMES = {
		VarClientID.TFA_CLIENT_NAME0, VarClientID.TFA_CLIENT_NAME1, VarClientID.TFA_CLIENT_NAME2,
		VarClientID.TFA_CLIENT_NAME3, VarClientID.TFA_CLIENT_NAME4, VarClientID.TFA_CLIENT_NAME5,
		VarClientID.TFA_CLIENT_NAME6, VarClientID.TFA_CLIENT_NAME7
	};
	// Slot 0 is the player themselves and has no varbit
	private static final int[] TFA_PARTY_SLOTS = {
		VarbitID.TFA_CLIENT_P1, VarbitID.TFA_CLIENT_P2, VarbitID.TFA_CLIENT_P3, VarbitID.TFA_CLIENT_P4,
		VarbitID.TFA_CLIENT_P5, VarbitID.TFA_CLIENT_P6, VarbitID.TFA_CLIENT_P7
	};

	private final Client client;

	@Inject
	public RaidParticipantReader(Client client)
	{
		this.client = client;
	}

	public List<String> read(String trigger)
	{
		List<String> party = raidPartyList(trigger);
		return party.isEmpty() ? scenePlayers() : party;
	}

	/**
	 * How many players the game says are in the party, or 0 when it does not say. The Fractured Archive keeps
	 * one varbit per party slot, which is set while a player fills it, so the count stays right even when the
	 * name list could not be read.
	 */
	public int gamesTeamSize(String trigger)
	{
		if (!trigger.startsWith(FRACTURED_ARCHIVE))
		{
			return 0;
		}
		return 1 + (int) Arrays.stream(TFA_PARTY_SLOTS).filter(slot -> client.getVarbitValue(slot) != 0).count();
	}

	private List<String> raidPartyList(String trigger)
	{
		if (trigger.startsWith(CHAMBERS_OF_XERIC))
		{
			return coxPartyNames();
		}
		if (trigger.startsWith(THEATRE_OF_BLOOD))
		{
			return partyNames(TOB_PARTY_NAMES);
		}
		if (trigger.startsWith(TOMBS_OF_AMASCUT))
		{
			return partyNames(TOA_PARTY_NAMES);
		}
		if (trigger.startsWith(FRACTURED_ARCHIVE))
		{
			return partyNames(TFA_PARTY_NAMES);
		}
		return Collections.emptyList();
	}

	private List<String> coxPartyNames()
	{
		Widget list = client.getWidget(InterfaceID.RaidsSidepanel.LIST);
		Widget[] children = list == null ? null : list.getChildren();
		if (children == null)
		{
			return Collections.emptyList();
		}
		return Arrays.stream(children)
			.filter(Objects::nonNull)
			.map(Widget::getName)
			.filter(Objects::nonNull)
			.map(Text::removeTags)
			.map(Text::sanitize)
			.filter(name -> !name.trim().isEmpty())
			.collect(Collectors.toList());
	}

	private List<String> partyNames(int[] varClientIds)
	{
		return Arrays.stream(varClientIds)
			.mapToObj(client::getVarcStrValue)
			.filter(Objects::nonNull)
			.map(Text::removeTags)
			.map(Text::sanitize)
			.filter(name -> !name.trim().isEmpty())
			.collect(Collectors.toList());
	}

	private List<String> scenePlayers()
	{
		WorldView worldView = client.getTopLevelWorldView();
		if (worldView == null)
		{
			return Collections.emptyList();
		}
		return worldView.players().stream()
			.filter(Objects::nonNull)
			.map(Actor::getName)
			.filter(Objects::nonNull)
			.map(Text::sanitize)
			.collect(Collectors.toList());
	}
}

package com.slayclan.task;

import com.slayclan.config.TaskDefinition;
import java.util.Collection;
import java.util.HashSet;
import java.util.List;
import java.util.Optional;
import java.util.Set;
import java.util.stream.Collectors;

public class ClogTaskEvaluator
{
	/**
	 * Returns the task's progress including {@code loggedItem}, using the item names as written in the task,
	 * or empty when the item is not part of the task.
	 */
	public Optional<Set<String>> progressAfter(TaskDefinition task, Set<String> currentProgress, String loggedItem)
	{
		List<String> items = task.getItems();
		if (items == null)
		{
			return Optional.empty();
		}
		return items.stream()
			.filter(item -> Names.matches(item, loggedItem))
			.findFirst()
			.map(item ->
			{
				Set<String> progress = new HashSet<>(currentProgress);
				progress.add(item);
				return progress;
			});
	}

	/**
	 * The listed items among a whole collection log, as opposed to one newly logged item.
	 */
	public Set<String> ownedOf(TaskDefinition task, Collection<String> ownedItems)
	{
		List<String> items = task.getItems();
		if (items == null)
		{
			return Set.of();
		}
		return items.stream()
			.filter(item -> ownedItems.stream().anyMatch(owned -> Names.matches(item, owned)))
			.collect(Collectors.toSet());
	}

	public boolean isComplete(TaskDefinition task, Set<String> progress)
	{
		return progress.size() >= Math.max(1, task.getRequired());
	}
}

package com.slayclan.task;

import com.slayclan.config.TaskDefinition;
import java.util.List;

public class LootTaskEvaluator
{
	public boolean matches(TaskDefinition task, String source, String itemName)
	{
		List<String> items = task.getItems();
		List<String> sources = task.getSources();
		boolean sourceAllowed = sources == null || sources.isEmpty() || sources.stream().anyMatch(allowed -> Names.same(allowed, source));
		return sourceAllowed && items != null && items.stream().anyMatch(pattern -> Names.matches(pattern, itemName));
	}
}

package com.slayclan.task;

/**
 * Compares task triggers and item names the way players type them: apostrophes cannot be typed in the
 * game chat, so they are ignored along with case.
 */
public final class Names
{
	private static final String WILDCARD = "*";

	private Names()
	{
	}

	public static boolean same(String a, String b)
	{
		return a != null && b != null && normalize(a).equals(normalize(b));
	}

	/**
	 * Like {@link #same}, except that a pattern ending in {@code *} matches every name starting with the rest.
	 */
	public static boolean matches(String pattern, String name)
	{
		if (pattern == null || name == null)
		{
			return false;
		}
		String trimmed = pattern.trim();
		if (!trimmed.endsWith(WILDCARD))
		{
			return same(trimmed, name);
		}
		return normalize(name).startsWith(normalize(trimmed.substring(0, trimmed.length() - WILDCARD.length())));
	}

	public static String normalize(String name)
	{
		return name.replaceAll("['’`]", "").trim().toLowerCase();
	}
}

package com.slayclan.task;

import com.slayclan.config.RemoteConfig;
import com.slayclan.config.TaskDefinition;
import java.util.Arrays;
import java.util.Collection;
import java.util.List;
import java.util.stream.Collectors;

public class TaskMatcher
{
	private static final String TRIGGER_ALTERNATIVE_SEPARATOR = "\\|";

	public List<TaskDefinition> match(RemoteConfig config, String trigger, int participantCount)
	{
		return match(config, List.of(trigger), participantCount);
	}

	/**
	 * Tasks matching any of several triggers that describe the same event, each task at most once.
	 */
	public List<TaskDefinition> match(RemoteConfig config, Collection<String> triggers, int participantCount)
	{
		return config.getTasks().stream()
			.filter(task -> triggers.stream().anyMatch(trigger -> matchesTrigger(task.getTrigger(), trigger)))
			.filter(task -> participantCount >= task.getMinPlayers())
			.collect(Collectors.toList());
	}

	public List<TaskDefinition> byTrigger(RemoteConfig config, String trigger)
	{
		return config.getTasks().stream()
			.filter(task -> matchesTrigger(task.getTrigger(), trigger))
			.collect(Collectors.toList());
	}

	private static boolean matchesTrigger(String taskTrigger, String trigger)
	{
		return taskTrigger != null && Arrays.stream(taskTrigger.split(TRIGGER_ALTERNATIVE_SEPARATOR))
			.anyMatch(alternative -> Names.matches(alternative.trim(), trigger));
	}
}

package com.slayclan.task;

import com.slayclan.config.TaskDefinition;
import java.util.List;
import java.util.Set;

public class ThresholdTaskEvaluator
{
	public boolean isEquipped(TaskDefinition task, Set<String> wornItemNames)
	{
		List<String> items = task.getItems();
		if (items == null || items.isEmpty())
		{
			return false;
		}
		long wornMatches = items.stream()
			.filter(pattern -> wornItemNames.stream().anyMatch(worn -> Names.matches(pattern, worn)))
			.count();
		return wornMatches >= Math.max(1, task.getRequired());
	}

	public boolean hasExperience(TaskDefinition task, long experience)
	{
		return experience >= task.getMinXp();
	}

	public boolean hasCount(TaskDefinition task, int count)
	{
		return count >= task.getMinCount();
	}
}

package com.slayclan.task;

import com.slayclan.config.TaskDefinition;
import com.slayclan.trigger.TimeParser;
import com.slayclan.trigger.TimedLine;
import com.slayclan.trigger.TimedLine.Kind;
import java.util.List;
import java.util.Optional;
import java.util.OptionalDouble;

public class TimedTaskFilter
{
	private static final String CHALLENGE_TIME_TYPE = "challenge";

	public boolean accepts(TaskDefinition task, List<TimedLine> times, int teamSize, int killCount)
	{
		if ((task.getTeamSize() > 0 && task.getTeamSize() != teamSize) || killCount < task.getMinKillCount())
		{
			return false;
		}
		String maxTime = task.getMaxTime();
		if (maxTime == null || maxTime.trim().isEmpty())
		{
			return true;
		}
		OptionalDouble limit = TimeParser.parseSeconds(maxTime);
		Optional<TimedLine> time = pick(times, CHALLENGE_TIME_TYPE.equalsIgnoreCase(task.getTimeType()) ? Kind.CHALLENGE : Kind.TOTAL);
		return limit.isPresent() && time.isPresent() && time.get().getSeconds() <= limit.getAsDouble();
	}

	private static Optional<TimedLine> pick(List<TimedLine> times, Kind preferred)
	{
		return times.stream().filter(line -> line.getKind() == preferred).findFirst()
			.or(() -> times.stream().filter(line -> line.getKind() == Kind.SINGLE).findFirst());
	}
}

