package com.slayclan.activity;

import com.slayclan.trigger.TimedLine.Kind;
import java.util.List;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;
import net.runelite.client.config.ConfigManager;
import org.junit.Test;
import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.verify;
import static org.mockito.Mockito.when;

public class ScaleBestStoreTest
{
	private final ConfigManager configManager = mock(ConfigManager.class);
	private final ScaleBestStore store = new ScaleBestStore(configManager);

	@Test
	public void anyKillIsFasterThanNothingStored()
	{
		assertTrue(store.isFasterThanStored(42L, "Yama", Kind.SINGLE, 1, 357.0));
	}

	@Test
	public void onlyAFasterKillBeatsTheStoredTimeForThatScale()
	{
		when(configManager.getConfiguration("slayclanmemory", "scalebest.42.yama.single.1")).thenReturn("357.0");

		assertTrue(store.isFasterThanStored(42L, "Yama", Kind.SINGLE, 1, 340.0));
		assertFalse(store.isFasterThanStored(42L, "Yama", Kind.SINGLE, 1, 357.0));
		assertTrue(store.isFasterThanStored(42L, "Yama", Kind.SINGLE, 2, 357.0));
	}

	@Test
	public void storesTheBestUnderBossTimeTypeAndTeamSize()
	{
		store.saveBest(42L, "Theatre of Blood: Hard Mode", Kind.CHALLENGE, 3, 900.0);

		verify(configManager).setConfiguration("slayclanmemory", "scalebest.42.theatre-of-blood-hard-mode.challenge.3", "900.0");
	}

	@Test
	public void remembersWhichBossesHadTheirGameBestReported()
	{
		assertFalse(store.isGameBestReported(42L, "Yama"));

		store.markGameBestReported(42L, "Yama");

		verify(configManager).setConfiguration("slayclanmemory", "gamebestreported.42.yama", "true");
	}

}

package com.slayclan.clan;

import java.util.List;
import net.runelite.api.clan.ClanMember;
import net.runelite.api.clan.ClanSettings;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;
import org.junit.Before;
import org.junit.Test;
import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.when;

public class ClanMembershipCheckerTest
{
	private final ClanMembershipChecker checker = new ClanMembershipChecker();
	private ClanSettings clan;

	@Before
	public void setUp()
	{
		clan = mock(ClanSettings.class);
		when(clan.getName()).thenReturn("SlayClan");
		when(clan.findMember("Clanmate")).thenReturn(mock(ClanMember.class));
		when(clan.findMember("Raidbuddy")).thenReturn(mock(ClanMember.class));
		when(clan.findMember("Iron Clanmate")).thenReturn(mock(ClanMember.class));
	}

	@Test
	public void acceptsPartyWhereEveryoneIsAMember()
	{
		assertTrue(checker.allMembers(clan, "SlayClan", List.of("Clanmate", "Raidbuddy")));
	}

	@Test
	public void rejectsPartyWithAnOutsider()
	{
		assertFalse(checker.allMembers(clan, "SlayClan", List.of("Clanmate", "Zezima")));
	}

	@Test
	public void rejectsWhenLoggedIntoAnotherClan()
	{
		assertFalse(checker.allMembers(clan, "OtherClan", List.of("Clanmate", "Raidbuddy")));
	}

	@Test
	public void comparesClanNameIgnoringCase()
	{
		assertTrue(checker.allMembers(clan, "slayclan", List.of("Clanmate")));
	}

	@Test
	public void rejectsWhenClanSettingsAreMissing()
	{
		assertFalse(checker.allMembers(null, "SlayClan", List.of("Clanmate")));
	}

	@Test
	public void recognizesExpectedClanWithoutCheckingPlayers()
	{
		assertTrue(checker.isClan(clan, "SlayClan"));
	}

	@Test
	public void rejectsOtherClanName()
	{
		assertFalse(checker.isClan(clan, "OtherClan"));
	}

	@Test
	public void rejectsClanCheckWithoutClanSettings()
	{
		assertFalse(checker.isClan(null, "SlayClan"));
	}

	@Test
	public void normalizesNonBreakingSpacesInNames()
	{
		assertTrue(checker.allMembers(clan, "SlayClan", List.of("Iron Clanmate")));
	}
}

package com.slayclan.config;

import com.google.gson.Gson;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Paths;
import java.util.Optional;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;
import org.junit.Test;

public class RemoteConfigParserTest
{
	private final RemoteConfigParser parser = new RemoteConfigParser(new Gson());

	@Test
	public void parsesValidConfig()
	{
		RemoteConfig config = parser.parse(TestConfigs.VALID_JSON).orElseThrow();

		assertEquals("SlayClan", config.getClanName());
		assertEquals(1, config.getTasks().size());
		TaskDefinition task = config.getTasks().get(0);
		assertEquals("cox", task.getId());
		assertEquals("Clan Raid", task.getName());
		assertEquals("RAID:Chambers of Xeric", task.getTrigger());
		assertEquals("Repeatable", task.getTier());
		assertEquals(10, task.getPoints());
		assertEquals(2, task.getMinPlayers());
	}

	@Test
	public void readsTheContentTheClanHasSwitchedOff()
	{
		String json = "{\"clanName\":\"SlayClan\","
			+ "\"ignoredContent\":[\"Fractured Archive\",\"Yama*\"],"
			+ "\"tasks\":[{\"id\":\"cox\",\"name\":\"Clan Raid\",\"trigger\":\"RAID:Chambers of Xeric\",\"tier\":\"Repeatable\",\"points\":10}]}";

		RemoteConfig config = parser.parse(json).orElseThrow();

		assertTrue(config.ignores("fractured archive"));
		assertTrue(config.ignores("Yama (Awakened)"));
		assertFalse(config.ignores("Chambers of Xeric"));
	}

	@Test
	public void acceptsASingleSwitchedOffNameWrittenWithoutBrackets()
	{
		String json = TestConfigs.VALID_JSON.replace("\"tasks\"", "\"ignoredContent\":\"Fractured Archive\",\"tasks\"");

		RemoteConfig config = parser.parse(json).orElseThrow();

		assertTrue(config.ignores("Fractured Archive"));
		assertFalse(config.ignores("Chambers of Xeric"));
	}

	@Test
	public void ignoresNothingWhenTheListIsMissing()
	{
		RemoteConfig config = parser.parse(TestConfigs.VALID_JSON).orElseThrow();

		assertFalse(config.ignores("Fractured Archive"));
	}

	@Test
	public void defaultsMinPlayersToOneWhenMissing()
	{
		String json = "{\"clanName\":\"SlayClan\","
			+ "\"tasks\":[{\"id\":\"cox\",\"name\":\"Clan Raid\",\"trigger\":\"RAID:Chambers of Xeric\",\"tier\":\"Repeatable\",\"points\":10}]}";

		RemoteConfig config = parser.parse(json).orElseThrow();

		assertEquals(1, config.getTasks().get(0).getMinPlayers());
		assertFalse(config.getTasks().get(0).isIncludeStackable());
	}

	@Test
	public void parsesDropValueFields()
	{
		String json = "{\"clanName\":\"SlayClan\","
			+ "\"tasks\":[{\"id\":\"drops\",\"name\":\"Valuable drop\",\"trigger\":\"DROP\",\"tier\":\"Repeatable\","
			+ "\"minValue\":10000,\"valuePerPoint\":10000,\"includeStackable\":true}]}";

		TaskDefinition task = parser.parse(json).orElseThrow().getTasks().get(0);

		assertEquals(10_000, task.getMinValue());
		assertEquals(10_000, task.getValuePerPoint());
		assertTrue(task.isIncludeStackable());
	}

	@Test
	public void parsesCollectionLogTaskFields()
	{
		String json = "{\"clanName\":\"SlayClan\","
			+ "\"tasks\":[{\"id\":\"dust\",\"name\":\"Dust to Dust\",\"trigger\":\"CLOG\",\"tier\":\"PvM\",\"points\":200,"
			+ "\"once\":true,\"items\":[\"Sanguine dust\",\"Metamorphic dust\"],\"required\":2}]}";

		TaskDefinition task = parser.parse(json).orElseThrow().getTasks().get(0);

		assertTrue(task.isOnce());
		assertFalse(task.isClanOnly());
		assertEquals(2, task.getItems().size());
		assertEquals(2, task.getRequired());
	}

	@Test
	public void parsesTheExampleConfigShippedInDocs() throws Exception
	{
		String json = new String(Files.readAllBytes(Paths.get("docs", "example-config.json")), StandardCharsets.UTF_8);

		RemoteConfig config = parser.parse(json).orElseThrow();

		assertEquals(53, config.getTasks().size());
		assertTrue(config.getTasks().stream().allMatch(task -> task.getTier() != null));
	}

	@Test
	public void readsTasksGroupedByTier()
	{
		String json = "{\"clanName\":\"SlayClan\","
			+ "\"tasks\":{"
			+ "\"Social\":[{\"id\":\"trial-by-fire\",\"trigger\":\"CLOG\"}],"
			+ "\"Valuable drops\":[{\"id\":\"drops\",\"trigger\":\"DROP\",\"tier\":\"Repeatable\"}]"
			+ "}}";

		RemoteConfig config = parser.parse(json).orElseThrow();

		assertEquals(2, config.getTasks().size());
		assertEquals("Social", config.getTasks().get(0).getTier());
		assertEquals("Repeatable", config.getTasks().get(1).getTier());
	}

	@Test
	public void rejectsGroupThatIsNotAList()
	{
		String json = "{\"clanName\":\"SlayClan\","
			+ "\"tasks\":{\"Social\":{\"id\":\"trial-by-fire\"}}}";

		assertFalse(parser.parse(json).isPresent());
	}

	@Test
	public void allowsLineCommentsAsSectionHeadings()
	{
		String json = "{\n"
			+ "  \"clanName\": \"SlayClan\",\n"
			+ "  \"tasks\": [\n"
			+ "    // Social\n"
			+ "    { \"id\": \"trial-by-fire\", \"trigger\": \"CLOG\" },\n"
			+ "    // Valuable drops\n"
			+ "    { \"id\": \"drops\", \"trigger\": \"DROP\" }\n"
			+ "  ]\n"
			+ "}";

		RemoteConfig config = parser.parse(json).orElseThrow();

		assertEquals(2, config.getTasks().size());
		assertEquals("drops", config.getTasks().get(1).getId());
	}

	@Test
	public void rejectsMalformedJson()
	{
		assertFalse(parser.parse("{not json").isPresent());
	}

	@Test
	public void rejectsEmptyBody()
	{
		assertFalse(parser.parse("").isPresent());
	}

	@Test
	public void rejectsMissingClanName()
	{
		String json = TestConfigs.VALID_JSON.replace("\"clanName\":\"SlayClan\",", "");

		assertFalse(parser.parse(json).isPresent());
	}

	@Test
	public void stillReadsAnOldClanConfigThatContainsTheBotAddress()
	{
		String json = TestConfigs.VALID_JSON.replace("\"tasks\"", "\"apiUrl\":\"https://bot.example/api/v1/posts\",\"tasks\"");

		assertEquals("SlayClan", parser.parse(json).orElseThrow().getClanName());
	}

	@Test
	public void rejectsTaskWithoutId()
	{
		String json = "{\"clanName\":\"SlayClan\","
			+ "\"tasks\":[{\"name\":\"Clan Raid\",\"trigger\":\"RAID:*\"}]}";

		assertFalse(parser.parse(json).isPresent());
	}

	@Test
	public void rejectsTaskIdWithColon()
	{
		String json = "{\"clanName\":\"SlayClan\","
			+ "\"tasks\":[{\"id\":\"ca:safe\",\"trigger\":\"CA:Just To Be Safe\"}]}";

		assertFalse(parser.parse(json).isPresent());
	}

	@Test
	public void rejectsDuplicateTaskIds()
	{
		String json = "{\"clanName\":\"SlayClan\","
			+ "\"tasks\":{\"Social\":[{\"id\":\"cox\",\"trigger\":\"RAID:*\"}],\"PvM\":[{\"id\":\"cox\",\"trigger\":\"KILL:Yama\"}]}}";

		assertFalse(parser.parse(json).isPresent());
	}

	@Test
	public void rejectsMissingTasks()
	{
		String json = "{\"clanName\":\"SlayClan\"}";

		Optional<RemoteConfig> result = parser.parse(json);

		assertFalse(result.isPresent());
	}
}

package com.slayclan.config;

import com.google.gson.Gson;
import java.util.concurrent.CompletableFuture;
import java.util.concurrent.TimeUnit;
import okhttp3.OkHttpClient;
import okhttp3.mockwebserver.MockResponse;
import okhttp3.mockwebserver.MockWebServer;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;
import org.junit.Before;
import org.junit.Rule;
import org.junit.Test;

public class RemoteConfigServiceTest
{
	@Rule
	public final MockWebServer server = new MockWebServer();

	private RemoteConfigService service;

	@Before
	public void setUp()
	{
		service = new RemoteConfigService(new OkHttpClient(), new Gson());
	}

	@Test
	public void storesConfigFromValidResponse() throws Exception
	{
		server.enqueue(new MockResponse().setBody(TestConfigs.VALID_JSON));

		refresh();

		assertEquals("SlayClan", service.current().getClanName());
	}

	@Test
	public void keepsPreviousConfigWhenResponseIsInvalid() throws Exception
	{
		server.enqueue(new MockResponse().setBody(TestConfigs.VALID_JSON));
		server.enqueue(new MockResponse().setBody("{not json"));

		refresh();
		refresh();

		assertEquals("SlayClan", service.current().getClanName());
	}

	@Test
	public void keepsPreviousConfigOnServerError() throws Exception
	{
		server.enqueue(new MockResponse().setBody(TestConfigs.VALID_JSON));
		server.enqueue(new MockResponse().setResponseCode(500));

		refresh();
		refresh();

		assertEquals("SlayClan", service.current().getClanName());
	}

	@Test
	public void clearsConfigWhenUrlIsBlank() throws Exception
	{
		server.enqueue(new MockResponse().setBody(TestConfigs.VALID_JSON));
		refresh();

		service.refresh("  ").get(5, TimeUnit.SECONDS);

		assertNull(service.current());
	}

	@Test
	public void reportsFailureWhenResponseIsInvalidAndClearsItOnSuccess() throws Exception
	{
		server.enqueue(new MockResponse().setBody("{not json"));
		server.enqueue(new MockResponse().setBody(TestConfigs.VALID_JSON));

		refresh();
		assertTrue(service.lastRefreshFailed());

		refresh();
		assertFalse(service.lastRefreshFailed());
	}

	@Test
	public void reportsFailureOnServerError() throws Exception
	{
		server.enqueue(new MockResponse().setResponseCode(500));

		refresh();

		assertTrue(service.lastRefreshFailed());
	}

	@Test
	public void reportsFailureForUnparseableUrl() throws Exception
	{
		service.refresh("not a url").get(5, TimeUnit.SECONDS);

		assertTrue(service.lastRefreshFailed());
		assertNull(service.current());
	}

	@Test
	public void blankUrlIsNotAFailure() throws Exception
	{
		service.refresh("  ").get(5, TimeUnit.SECONDS);

		assertFalse(service.lastRefreshFailed());
	}

	@Test
	public void startsWithoutConfig()
	{
		assertNull(service.current());
	}

	@Test
	public void rejectsPlainHttpOutsideLoopback() throws Exception
	{
		service.refresh("http://example.com/config.json").get(5, TimeUnit.SECONDS);

		assertTrue(service.lastRefreshFailed());
		assertNull(service.current());
	}

	@Test
	public void rejectsOversizedBody() throws Exception
	{
		server.enqueue(new MockResponse().setBody(new String(new char[(int) RemoteConfigService.MAX_BODY_BYTES + 1]).replace('\0', ' ')));

		refresh();

		assertTrue(service.lastRefreshFailed());
		assertNull(service.current());
	}

	@Test
	public void dropsOldConfigWhenANewUrlFails() throws Exception
	{
		server.enqueue(new MockResponse().setBody(TestConfigs.VALID_JSON));
		server.enqueue(new MockResponse().setResponseCode(404));

		refresh();
		service.refresh(localUrl("/other.json")).get(5, TimeUnit.SECONDS);

		assertTrue(service.lastRefreshFailed());
		assertNull(service.current());
	}

	@Test
	public void slowResponseForAnOldUrlDoesNotReplaceANewerConfig() throws Exception
	{
		server.enqueue(new MockResponse().setBody(TestConfigs.VALID_JSON).setBodyDelay(500, TimeUnit.MILLISECONDS));
		server.enqueue(new MockResponse().setBody(TestConfigs.VALID_JSON.replace("SlayClan", "NewClan")));

		CompletableFuture<Void> slow = service.refresh(localUrl("/old.json"));
		server.takeRequest();
		service.refresh(localUrl("/new.json")).get(5, TimeUnit.SECONDS);
		slow.get(5, TimeUnit.SECONDS);

		assertEquals("NewClan", service.current().getClanName());
	}

	@Test
	public void responseArrivingAfterTheConfigWasClearedIsIgnored() throws Exception
	{
		server.enqueue(new MockResponse().setBody(TestConfigs.VALID_JSON).setBodyDelay(500, TimeUnit.MILLISECONDS));

		CompletableFuture<Void> slow = service.refresh(localUrl("/config.json"));
		server.takeRequest();
		service.refresh(null).get(5, TimeUnit.SECONDS);
		slow.get(5, TimeUnit.SECONDS);

		assertNull(service.current());
	}

	@Test
	public void rejectsPlainHttpToAHostThatOnlyLooksLikeLoopback() throws Exception
	{
		service.refresh("http://127.example.com/config.json").get(5, TimeUnit.SECONDS);

		assertTrue(service.lastRefreshFailed());
		assertEquals(0, server.getRequestCount());
	}

	private void refresh() throws Exception
	{
		service.refresh(localUrl("/config.json")).get(5, TimeUnit.SECONDS);
	}

	// MockWebServer may report the machine name as host, which the https rule would reject
	private String localUrl(String path)
	{
		return "http://localhost:" + server.getPort() + path;
	}
}

